mapper.select:
SELECT DISTINCT req_id FROM smartbusmngdb.sbm_facility_cmd_target WHERE facility_id IN
#{fid}
AND target_status IN ('PENDING','SENDING','SENT','RETRY')

mapper.update:
UPDATE smartbusmngdb.sbm_facility_cmd_target SET target_status = 'CANCELED', last_error = 'canceled_by_new_request', next_retry_dt = NULL, worker_id = NULL, picked_dt = NULL, last_updt_dt = CURRENT_TIMESTAMP WHERE facility_id IN
#{fid}
AND target_status IN ('PENDING','SENDING','RETRY')

mapper.insert:
INSERT INTO smartbusmngdb.sbm_facility_emermsg
(
	target_id, facility_id, emergency_msg, frst_regist_dt, frst_user_id, frst_regist_tool
)
VALUES
(
	#{targetId}, #{facilityId}, #{emergencyMsg}, CURRENT_TIMESTAMP, #{userId}, #{tool}
)

mapper.select:
SELECT t.target_id AS targetId, t.req_id AS reqId, t.facility_id AS facilityId, t.msg_id AS msgId, t.cmd_tp AS cmdTp, t.cmd_msg AS cmdMsg,
r.retain_yn AS retainYn, r.qos AS qos,
t.target_status AS targetStatus, t.publish_dt AS publishDt, t.ack_dt AS ackDt, t.ack_code AS ackCode, t.ack_msg AS ackMsg, t.retry_cnt AS retryCnt, t.next_retry_dt AS nextRetryDt, t.worker_id AS workerId, t.picked_dt AS pickedDt, t.last_error AS lastError FROM smartbusmngdb.sbm_facility_cmd_target t JOIN smartbusmngdb.sbm_facility_cmd_req r ON r.req_id = t.req_id WHERE t.worker_id = #{workerId} AND t.target_status = 'SENDING' ORDER BY t.picked_dt ASC, t.target_id ASC LIMIT #{limit}
